    T = int(data[idx]); idx += 1
    out = []
    for _ in range(T):
        N = int(data[idx]); idx += 1
        L = 2 * N
        A = [int(x) for x in data[idx:idx+L]]
        idx += L

        groups = defaultdict(list)
        for i in range(L - 1):
            x = A[i]
            y = A[i+1]
            if x != y:
                key = (x, y) if x < y else (y, x)
                groups[key].append(i)

        ans = 0
        for lst in groups.values():
            k = len(lst)
            if k < 2:
                continue
            for a in range(k):
                ia = lst[a]
                for b in range(a+1, k):
                    jb = lst[b]
                    d = jb - ia
                    if d == 1:
                        continue
                    elif d == 2:
                        if A[ia] == A[jb]:
                            ans += 1
                    else:
                        ans += 1

        out.append(str(ans))

    sys.stdout.write('\n'.join(out) + '\n')

